define({"topics":[{"title":"Running the fMRI Quality Assurance (QA) tool in Basic mode","shortdesc":"<p class=\"shortdesc\">Run the fMRI Quality Assurance (QA) tool in Basic mode to complete automatic acquisition using fBIRN protocol, analyze the images, report results, and archive the results without user intervention.<\/p>","href":"t_RunningTheFMRIQAToolInBasicMode.html","attributes":{"data-id":"id_2004510"},"menu":{"hasChildren":false},"tocID":"id_2004510-d46e18917","topics":[]},{"title":"Running the fMRI Quality Assurance (QA) tool in Expert mode","shortdesc":"<p class=\"shortdesc\">Run the fMRI Quality Assurance (QA) tool in Expert mode to load an fMRI QA protocol matching the system configuration (wide or non-wide), load and view images, do customizable stability and ghosting analysis, archive data, and view protocol details. <\/p>","href":"t_RunningTheFMRIQAToolInExpertMode.html","attributes":{"data-id":"id_2004511"},"menu":{"hasChildren":false},"tocID":"id_2004511-d46e19021","topics":[]}]});